var JOGO = (typeof window !== 'undefined')
  ? (window.JOGO = window.JOGO || {})
  : (globalThis.JOGO = globalThis.JOGO || {});
/* SOTERRA 2.0 - personagens do usuario, gerados no Meshy
 *
 * Cada classe chegou como SEIS .glb de ~20 MB (um por animacao), num total
 * de 126 MB por personagem. Mas os seis eram REDUNDANTES: cada arquivo ja
 * trazia todas as acoes. E os 20 MB eram quase so uma textura 4096x4096.
 *
 * Aqui e um arquivo por classe, textura em 1024 px, com as seis acoes
 * renomeadas para os papeis que o jogo pede (idle/walk/run/attack/hit/death)
 * — o Meshy nomeia diferente em cada personagem e o renderizador nao pode
 * depender disso.
 *
 * ~15 mil triangulos e 24 ossos por personagem: densidade de jogo, nao de
 * escultura. Nao precisou decimar.
 */
JOGO.MODELS = JOGO.MODELS || {};
JOGO.MESHY_CLIPS = JOGO.MESHY_CLIPS || {};
JOGO.MODELS['meshy_sumo']='';
JOGO.MESHY_CLIPS['meshy_sumo']=['HitReact','attack','death','idle','run','walk'];
JOGO.MODELS['meshy_invocador']='';
JOGO.MESHY_CLIPS['meshy_invocador']=['Dodge','attack','death','hit','idle','run','walk'];
JOGO.MODELS['meshy_espadachim']='';
JOGO.MESHY_CLIPS['meshy_espadachim']=['Dodge','HitReact','attack','death','idle','run','walk'];
JOGO.MODELS['meshy_minotauro']='';
JOGO.MESHY_CLIPS['meshy_minotauro']=['Dodge','HitReact','attack','death','idle','run','walk'];
JOGO.MODELS['meshy_curandeiro']='';
JOGO.MESHY_CLIPS['meshy_curandeiro']=['HitReact','attack','death','idle','run','walk'];
JOGO.MODELS['meshy_arqueiro']='';
JOGO.MESHY_CLIPS['meshy_arqueiro']=['Dodge','HitReact','attack','death','idle','run','walk'];
JOGO.MODELS['meshy_bruxo']='';
JOGO.MESHY_CLIPS['meshy_bruxo']=['attack','death','hit','idle','run','walk'];
